import{_ as s,o as t,c as a,a4 as i}from"./chunks/framework.DCsBdTIw.js";const k=JSON.parse(`{"title":"Hermes Agent","description":"Connect Nous Research's Hermes Agent to Tokeness, including the prompt-caching setting that custom gateways must declare explicitly.","frontmatter":{"title":"Hermes Agent","description":"Connect Nous Research's Hermes Agent to Tokeness, including the prompt-caching setting that custom gateways must declare explicitly."},"headers":[],"relativePath":"integrations/hermes.md","filePath":"integrations/hermes.md","lastUpdated":1784332800000}`),n={name:"integrations/hermes.md"};function o(l,e,d,h,r,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="hermes-agent" tabindex="-1">Hermes Agent <a class="header-anchor" href="#hermes-agent" aria-label="Permalink to &quot;Hermes Agent&quot;">​</a></h1><p>Hermes Agent is an open-source agent from Nous Research. It supports two transports: the OpenAI-compatible Chat Completions wire, and the native Anthropic Messages wire. Tokeness supports both.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Transport</td><td><code>anthropic_messages</code> (recommended for Claude) or <code>openai_chat</code></td></tr><tr><td>Base URL (<code>anthropic_messages</code>)</td><td><code>https://n.tokeness.dev</code></td></tr><tr><td>Base URL (<code>openai_chat</code>)</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>The full model name copied from the Tokeness console</td></tr></tbody></table><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>In the Tokeness console:</p><ol><li>Confirm the wallet balance is available.</li><li>Create an API key dedicated to Hermes.</li><li>Copy the full model name you intend to use (for example <code>claude-opus-5-5</code>).</li><li>Open the usage logs — you will use them later to verify requests.</li></ol><h2 id="_2-configure-hermes" tabindex="-1">2. Configure Hermes <a class="header-anchor" href="#_2-configure-hermes" aria-label="Permalink to &quot;2. Configure Hermes&quot;">​</a></h2><p>Edit <code>~/.hermes/config.yaml</code>. <strong>Configure Tokeness as a custom provider (<code>provider: custom</code>)</strong> so the entry carries its own key — this avoids Hermes&#39; Anthropic credential priority (<code>ANTHROPIC_TOKEN</code> / Claude Code credentials) shadowing your Tokeness key or sending it to the wrong endpoint:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-5-5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic_messages</span></span></code></pre></div><p><code>api_mode</code> selects the transport; both are supported:</p><table tabindex="0"><thead><tr><th><code>api_mode</code></th><th>Protocol</th><th>Endpoint used</th></tr></thead><tbody><tr><td><code>anthropic_messages</code></td><td>Native Anthropic Messages</td><td><code>https://n.tokeness.dev/v1/messages</code></td></tr><tr><td><code>chat_completions</code></td><td>OpenAI-compatible</td><td><code>https://n.tokeness.dev/v1/chat/completions</code></td></tr></tbody></table><p>For the OpenAI-compatible transport, include <code>/v1</code> in <code>base_url</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-5-5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chat_completions</span></span></code></pre></div><p>Do not append <code>/v1</code> twice (<code>https://n.tokeness.dev/v1/v1</code> returns 404). Keep the API key in <code>~/.hermes/.env</code> rather than in <code>config.yaml</code>.</p><h2 id="_3-enable-prompt-caching-explicitly" tabindex="-1">3. Enable prompt caching explicitly <a class="header-anchor" href="#_3-enable-prompt-caching-explicitly" aria-label="Permalink to &quot;3. Enable prompt caching explicitly&quot;">​</a></h2><p>Anthropic prompt caching is <strong>explicit</strong>: the request must carry a <code>cache_control</code> breakpoint before the upstream caches that prefix. Without one, every turn re-bills the entire context at full input price. Hermes injects those breakpoints on its own, but only for providers, hosts, and model families it recognises. Tokeness is a custom endpoint, so Hermes defaults to the conservative choice and injects none.</p><p>This is why switching transport alone (<code>api_mode</code> set to Anthropic) does not improve the hit rate — the transport does not change that decision. Only an explicit declaration does.</p><p>Declare the capability on the model under its provider entry. <strong><code>api</code> must match <code>model.base_url</code> exactly</strong> (Hermes matches routes on the normalized address, so <code>/v1</code> vs no <code>/v1</code> are two different routes):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prompt_caching</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cache_ttl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5m&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or &quot;1h&quot;; defaults to 5m when omitted</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tokeness</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # keep identical to model.base_url</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    transport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic_messages</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # or openai_chat</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${TOKENESS_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    discover_models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # see step 4</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      claude-opus-5-5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        prompt_caching</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Notes:</p><ul><li><code>api</code> must be written the same way as <code>model.base_url</code> (with or without <code>/v1</code>); otherwise the declaration does not match and caching stays off.</li><li>The key under <code>models:</code> must match the full model name from the console exactly.</li><li><code>transport</code> selects the marker layout: <code>openai_chat</code> uses the OpenAI envelope layout, <code>anthropic_messages</code> uses the native inner-block layout. Tokeness converts both correctly, so you do not need to change transport for caching.</li><li>When <code>prompt_caching</code> is omitted, Hermes stays conservative and injects nothing; <code>false</code> disables markers explicitly.</li><li>With <code>api_mode: anthropic_messages</code>, Hermes <code>v2026.8.27</code> and later also inject breakpoints for Claude models automatically. The explicit declaration is still the safer choice, and on the OpenAI-compatible transport it is the only way to enable caching.</li></ul><p>Optionally set the cache TTL (default 5 minutes; use 1 hour for long sessions with pauses between turns):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prompt_caching</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cache_ttl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5m&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or &quot;1h&quot;</span></span></code></pre></div><h2 id="_4-set-the-model-name-manually" tabindex="-1">4. Set the model name manually <a class="header-anchor" href="#_4-set-the-model-name-manually" aria-label="Permalink to &quot;4. Set the model name manually&quot;">​</a></h2><p>Tokeness <code>/v1/models</code> returns only the public group (<code>default</code>) catalog. Paid groups such as Claude and GPT are not part of that public list, so Hermes&#39; model discovery returns an empty list for them. Set <code>discover_models</code> to <code>false</code> and enter the full model name from the console; calls work normally.</p><h2 id="_5-verify-that-caching-is-active" tabindex="-1">5. Verify that caching is active <a class="header-anchor" href="#_5-verify-that-caching-is-active" aria-label="Permalink to &quot;5. Verify that caching is active&quot;">​</a></h2><ol><li>Hermes prints the cache status at startup, for example <code>💾 Prompt caching: ENABLED</code>.</li><li>In the Tokeness console, open the request in the <strong>usage logs</strong> and check <code>Cache Write</code> and <code>Cache Read</code>.</li><li>For a multi-turn conversation:</li></ol><table tabindex="0"><thead><tr><th>Turn</th><th>Expected</th></tr></thead><tbody><tr><td>First turn</td><td><code>Cache Write</code> greater than 0; input tokens small (the written part is billed at the write rate)</td></tr><tr><td>Later turns</td><td><code>Cache Read</code> greater than 0; input tokens also small</td></tr></tbody></table><p>If every turn shows input tokens close to the whole context and <code>Cache Read</code> stays at 0, the breakpoints are not being sent — go back to step 3 and check the declaration.</p><h2 id="_6-troubleshooting" tabindex="-1">6. Troubleshooting <a class="header-anchor" href="#_6-troubleshooting" aria-label="Permalink to &quot;6. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>401</td><td>Check the API key; the <code>anthropic_messages</code> transport uses <code>x-api-key</code>, the OpenAI-compatible transport uses <code>Authorization: Bearer</code></td></tr><tr><td>404</td><td>For <code>anthropic_messages</code>, set <code>base_url</code> to <code>https://n.tokeness.dev</code> (do not add <code>/v1</code>); for the OpenAI-compatible transport use <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>model not found</td><td>Copy the full model name from the console, then set <code>discover_models</code> to <code>false</code> and enter it manually</td></tr><tr><td>Large input tokens every turn and <code>Cache Read</code> stays at 0</td><td>Confirm <code>prompt_caching: true</code> is declared; confirm <code>providers.&lt;name&gt;.api</code> matches <code>model.base_url</code> exactly; confirm the key under <code>models:</code> matches the console model name</td></tr><tr><td>Changed the caching config but nothing improved</td><td>The declaration takes effect from Hermes <code>v2026.8.27</code>; check the version first</td></tr><tr><td>Cost jumps after a mid-session model switch</td><td>Caches are keyed to the model, so the first turn after a switch always re-reads the whole context at full price</td></tr></tbody></table>`,32)])])}const m=s(n,[["render",o]]);export{k as __pageData,m as default};
